function normalizePersianText(input) {
	if (input === null || input === void 0) return "";
	return String(input).normalize("NFKC").replace(/ي/g, "ی").replace(/ى/g, "ی").replace(/ك/g, "ک").replace(/[ۀة]/g, "ه").replace(/[\u064B-\u065F\u0670]/g, "").replace(/\u200c/g, " ").replace(/[۰-۹]/g, (d) => String("۰۱۲۳۴۵۶۷۸۹".indexOf(d))).replace(/[٠-٩]/g, (d) => String("٠١٢٣٤٥٦٧٨٩".indexOf(d))).replace(/\s+/g, " ").trim().toLowerCase();
}
function toPersianDigits(input) {
	if (input === null || input === void 0) return "";
	return String(input).replace(/[0-9]/g, (d) => "۰۱۲۳۴۵۶۷۸۹"[Number(d)]);
}
function toEnglishDigits(input) {
	if (input === null || input === void 0) return "";
	return String(input).replace(/[۰-۹]/g, (d) => String("۰۱۲۳۴۵۶۷۸۹".indexOf(d))).replace(/[٠-٩]/g, (d) => String("٠١٢٣٤٥٦٧٨٩".indexOf(d)));
}
