/**
* لایه ذخیره‌سازی آفلاین IndexedDB برای سامانه مدیریت کتابخانه و پژوهش مرکز اسناد گلزار شهدای تهران
* مطابق بخش ۱۳ مأموریت جامع: همگام‌سازی خودکار IndexedDB و localStorage برای پایداری کامل در حالت آفلاین
*/
var DB_NAME = "MarkazAsnadLibraryDB";
var DB_VERSION = 1;
var STORE_NAME = "keyval_store";
function openDatabase() {
	return new Promise((resolve, reject) => {
		if (typeof indexedDB === "undefined") {
			reject(/* @__PURE__ */ new Error("IndexedDB not supported"));
			return;
		}
		const request = indexedDB.open(DB_NAME, DB_VERSION);
		request.onupgradeneeded = () => {
			const db = request.result;
			if (!db.objectStoreNames.contains(STORE_NAME)) db.createObjectStore(STORE_NAME);
		};
		request.onsuccess = () => resolve(request.result);
		request.onerror = () => reject(request.error);
	});
}
async function idbSetItem(key, value) {
	try {
		const db = await openDatabase();
		await new Promise((resolve, reject) => {
			const tx = db.transaction(STORE_NAME, "readwrite");
			tx.objectStore(STORE_NAME).put(value, key);
			tx.oncomplete = () => resolve();
			tx.onerror = () => reject(tx.error);
		});
	} catch {}
}
async function idbGetItem(key) {
	try {
		const db = await openDatabase();
		return await new Promise((resolve, reject) => {
			const req = db.transaction(STORE_NAME, "readonly").objectStore(STORE_NAME).get(key);
			req.onsuccess = () => resolve(req.result ?? null);
			req.onerror = () => reject(req.error);
		});
	} catch {
		return null;
	}
}
